class Solution:
    def oddCells(self, m: int, n: int, indices: list[list[int]]) -> int:
        rows = [0] * m
        cols = [0] * n
        for r, c in indices:
            rows[r] ^= 1
            cols[c] ^= 1
        odd_r = sum(rows)
        odd_c = sum(cols)
        return odd_r * (n - odd_c) + (m - odd_r) * odd_c

class Solution {
public:
    int oddCells(int m, int n, std::vector<std::vector<int>>& indices) {
        std::vector<int> rows(m, 0), cols(n, 0);
        for (const auto& idx : indices) {
            rows[idx[0]] ^= 1;
            cols[idx[1]] ^= 1;
        }
        int oddR = 0, oddC = 0;
        for (int r : rows) oddR += r;
        for (int c : cols) oddC += c;
        return oddR * (n - oddC) + (m - oddR) * oddC;
    }
};

